5	/** The gallery's status for a repo row, or null while it has no result. A passed code fix waits for approval. */
6	function badgeStatus(r: InstallRepo): string | null {
7	  if (!r.result) return null;
8	  if (r.needs_approval && (r.result === "runs" || r.result === "runs_with_gaps")) return "fix_awaiting_approval";
9	  return r.result;
10	}
11	
12	const STATE_WORD: Record<string, string> = { queued: "Queued", checking: "Checking", done: "Done", skipped: "Skipped" };
13	
14	function RepoRow({ r, i }: { r: InstallRepo; i: number }) {
15	  const status = badgeStatus(r);
16	  return (
17	    <li className="settle flex flex-wrap items-center gap-x-4 gap-y-2 px-4 py-3" style={{ "--i": i } as React.CSSProperties}>
18	      <span className="min-w-0 flex-1 break-words font-semibold">
19	        {r.repo}
20	        {r.path ? <span className="font-normal text-muted-foreground">/{r.path}</span> : null}
21	        {r.sha ? <span className="ml-2 font-mono text-sm font-normal text-muted-foreground">{r.sha}</span> : null}
22	      </span>
23	      <span className="font-mono text-sm text-muted-foreground">{STATE_WORD[r.state] ?? r.state}</span>
24	      {status && <StatusBadge status={status} />}
25	      {r.run_id && (
26	        <Link to={`/runs/${r.run_id}`} className="text-sm font-semibold underline underline-offset-4 hover:text-accent-strong">
27	          Open the run
28	        </Link>
29	      )}
30	      {r.pr?.url && (
31	        <a href={r.pr.url} className="text-sm font-semibold underline underline-offset-4 hover:text-accent-strong">
32	          Pull request{r.pr.number != null ? ` #${r.pr.number}` : ""}
33	        </a>
34	      )}
35	      {r.state === "skipped" && r.reason && <p className="basis-full text-sm text-muted-foreground">{r.reason}</p>}
36	    </li>
37	  );
38	}
