40	export default function Installed() {
41	  const { id = "" } = useParams();
42	  const queueFull = useSearchParams()[0].get("queue") === "full";
43	  const { data, error, loading } = useInstallation(id);
44	  const repos = data?.repos ?? [];
45	  const finished = data?.state === "done" || data?.state === "rejected";
46	
47	  return (
48	    <main className="mx-auto w-full max-w-3xl px-4 pb-24 pt-12 sm:px-6">
49	      <Eyebrow>GitHub App</Eyebrow>
50	      <h1 className="text-5xl font-semibold tracking-tight sm:text-6xl">Resurgo Agent is installed.</h1>
51	      <p className="mt-5 text-lg text-muted-foreground">
52	        Resurgo checks each repo you picked in a fresh container, one at a time, and opens a pull request only for a fix that
53	        passed in a clean container. Code changes wait for your approval.{" "}
54	        <Link to="/data" className="underline underline-offset-4 hover:text-foreground">What Resurgo stores</Link>
55	      </p>
56	
57	      <section className="mt-10" aria-label="Installation status" aria-live="polite">
58	        {loading && <p className="text-muted-foreground" role="status">◌ Loading…</p>}
59	
60	        {!data && !loading && queueFull && (
61	          <p role="status">
62	            <span aria-hidden className="font-mono">◌ </span>The check queue is full right now, so this installation was not queued.{" "}
63	            <a href={`/auth/github/callback?installation_id=${encodeURIComponent(id)}&setup_action=install`} className="font-semibold underline underline-offset-4 hover:text-accent-strong">
64	              Queue the check again
65	            </a>
66	          </p>
67	        )}
68	        {!data && !loading && !queueFull && (
69	          <p className="text-muted-foreground" role="status">
70	            <span aria-hidden className="font-mono">◌ </span>
71	            {error === "Not found" ? `No record of installation ${id} yet.` : "Unable to load the status. Reload the page to try again."}
72	          </p>
73	        )}
74	
75	        {data && (
76	          <>
77	            <p className="font-mono text-sm text-muted-foreground">
78	              Installation {data.installation_id}
79	              {data.account ? ` · ${data.account}` : ""}
80	              {!finished && repos.length > 0 ? " · updating every 5 s" : ""}
81	            </p>
82	
83	            {data.state === "rejected" && (
84	              <p className="mt-4" role="status">
85	                <span aria-hidden className="font-mono">✗ </span>
86	                Resurgo did not run checks for this installation{data.reason ? `: ${data.reason}` : "."}
87	              </p>
88	            )}
89	
90	            {data.state !== "rejected" && repos.length === 0 && (
91	              <p className="mt-4 text-muted-foreground" role="status">
92	                <span aria-hidden className="font-mono">◌ </span>
93	                {data.state === "done" ? (
94	                  <>
95	                    No public repositories in this installation.{" "}
96	                    <a href="https://github.com/apps/resurgo-agent/installations/new" className="font-semibold underline underline-offset-4 hover:text-accent-strong">
97	                      Add one in the app&apos;s settings on GitHub
98	                    </a>
99	                    .
100	                  </>
101	                ) : (
102	                  "Waiting for the runner to pick this up."
103	                )}
104	              </p>
105	            )}
106	
107	            {repos.length > 0 && (
108	              <ul className="mt-4 divide-y divide-border rounded-lg border border-border bg-panel" role="list">
109	                {repos.map((r, i) => (
110	                  <RepoRow key={`${r.repo}/${r.path ?? ""}`} r={r} i={i} />
111	                ))}
112	              </ul>
113	            )}
114	          </>
115	        )}
116	      </section>
117	
118	      <p className="mt-10">
119	        <Link to="/runs" className="text-sm font-semibold underline underline-offset-4 hover:text-accent-strong">See every recorded run</Link>
120	      </p>
121	    </main>
122	  );
123	}
