1	import { useEffect, useMemo, useRef, useState, type CSSProperties } from "react";
2	import { animate, useReducedMotion } from "motion/react";
3	import { AnimIcon, type IconName } from "@/components/art";
4	import { panelId, tabId, TabList } from "@/components/Tabs";
5	import type { RunDetail } from "@/lib/api";
6	import { EASE_ENTER } from "@/lib/ease";
7	import { cleanLine, fmtDur, parsePatch, statusMeta, stepOk } from "@/lib/run";
8	import { readingMs, useStream } from "@/lib/stream";
9	import { cn } from "@/lib/utils";
10	
11	type TabKey = "check" | "diagnose" | "repair" | "prove";
12	
13	const TABS: { id: TabKey; label: string; icon: IconName; blurb: string }[] = [
14	  { id: "check", label: "Check", icon: "check", blurb: "Clone fresh, then install, build, test and start, stopping at the first failure." },
15	  { id: "diagnose", label: "Diagnose", icon: "diagnose", blurb: "Deterministic rules first. The model only runs when something broke." },
16	  { id: "repair", label: "Repair", icon: "repair", blurb: "The smallest change that could work, written as a patch." },
17	  { id: "prove", label: "Prove", icon: "prove", blurb: "A second container clones the same commit, applies only the fix and reruns every step. Only that counts." },
18	];
19	
20	type Line = { text: string; tone?: "bad" | "added" | "muted" | "good" };
21	type Stat = { label: string; value: string };
22	type Content = { title: string; lines: Line[]; stats: Stat[] };
23	
24	const ERROR_LINE = /error|ERR_|failed|timed out|fatal|exit code|cannot|not found|ignored build/i;
25	
26	/** Real excerpt and real stat cards for one tab. A stat with no measurement is simply left out. */
27	function contentFor(tab: TabKey, d: RunDetail): Content {
28	  const r = d.result;
29	  const steps = r.agent?.steps ?? [];
30	  const attempts = r.agent?.attempts ?? [];
31	  const calls = r.model_calls ?? [];
32	  const stats: Stat[] = [];
33	  const add = (label: string, value: string | number | null | undefined) => {
34	    if (value !== null && value !== undefined && value !== "" && value !== "—") stats.push({ label, value: String(value) });
35	  };
36	
37	  if (tab === "check") {
38	    const failIdx = steps.findIndex((s) => !stepOk(s));
39	    const upTo = failIdx >= 0 ? steps.slice(0, failIdx + 1) : steps;
40	    const failed = failIdx >= 0 ? steps[failIdx] : null;
41	    const lines: Line[] = [];
42	    if (failed) {
43	      lines.push({ text: `$ ${failed.command}`, tone: "muted" });
44	      const tail = (failed.output_tail ?? []).map(cleanLine).filter((l) => l.trim());
45	      const errs = tail.filter((l) => ERROR_LINE.test(l));
46	      for (const l of (errs.length ? errs : tail.slice(-3)).slice(0, 5)) lines.push({ text: l, tone: "bad" });
47	    } else {
48	      for (const s of steps) lines.push({ text: `✓ ${s.name}  ${fmtDur(s.duration_s)}`, tone: "good" });
49	    }
50	    add(failed ? "Steps before it stopped" : "Steps passed", upTo.length || null);
51	    add(failed ? "Time to the first failure" : "Time in the agent container", fmtDur(upTo.reduce((a, s) => a + (s.duration_s ?? 0), 0)));
52	    add("Stopped at", failed?.name);
53	    return { title: `${r.repo} · check`, lines, stats };
54	  }
55	
56	  if (tab === "diagnose") {
57	    const a = attempts[0];
58	    const lines: Line[] = a?.rationale
59	      ? [{ text: `“${a.rationale}”` }]
60	      : r.agent?.rules_fired?.length
61	        ? [{ text: `Rule fired: ${r.agent.rules_fired[0]}. No model call was needed.` }]
62	        : [{ text: "This run needed no diagnosis." }];
63	    add("Model calls", calls.length || null);
64	    add("Time thinking", calls.length ? fmtDur(calls.reduce((s, c) => s + (c.duration_s ?? 0), 0)) : null);
65	    add("Confidence", a?.confidence != null ? a.confidence.toFixed(2) : null);
66	    add("Model", calls.find((c) => c.model)?.model);
67	    return { title: `${r.repo} · diagnose`, lines, stats };
68	  }
69	
70	  if (tab === "repair") {
71	    const files = d.fix_patch ? parsePatch(d.fix_patch) : [];
72	    const lines: Line[] = [];
73	    for (const f of files) {
74	      lines.push({ text: f.title, tone: "muted" });
75	      for (const l of f.lines.slice(0, 8)) {
76	        lines.push({ text: `${l.kind === "added" ? "+" : l.kind === "removed" ? "-" : " "} ${l.content}`, tone: l.kind === "added" ? "added" : "muted" });
77	      }
78	    }
79	    if (!lines.length) lines.push({ text: "No patch was recorded for this run." });
80	    add("Repair attempts", attempts.length || null);
81	    add("Files changed", files.length || null);
82	    add("Lines added", files.reduce((n, f) => n + f.lines.filter((l) => l.kind === "added").length, 0) || null);
83	    return { title: `${r.repo} · repair`, lines, stats };
84	  }
85	
86	  const v = r.verifier?.steps ?? [];
87	  const lines: Line[] = v.length
88	    ? v.map((s) => ({ text: `${stepOk(s) ? "✓" : "✗"} ${s.name}  ${fmtDur(s.duration_s)}`, tone: stepOk(s) ? ("good" as const) : ("bad" as const) }))
89	    : [{ text: "The clean container was never reached for this run." }];
90	  add("Clean-container steps passed", v.length ? `${v.filter(stepOk).length} of ${v.length}` : null);
91	  add("Time in the clean container", v.length ? fmtDur(v.reduce((a, s) => a + (s.duration_s ?? 0), 0)) : null);
92	  add("Verdict", statusMeta(d.summary.status).word);
93	  return { title: `${r.repo} · clean container`, lines, stats };
94	}
95	
96	/** The beam's staging: icons draw first (about 1 s), then one beam runs the connector in 1.4 s. */
97	const BEAM_LEAD_MS = 1100;
98	const BEAM_MS = 1400;
99	
100	/** The node that sits at the start of one stage on the connector. Its fill comes on as the beam leaves it. */
101	const BeamNode = ({ i }: { i: number }) => (
102	  <span aria-hidden className="beam-node" style={{ "--i": i } as CSSProperties}>
103	    <span className="beam-node-fill" />
104	  </span>
105	);
106	
107	/** The stretch of connector from one stage to the next (none after the last). */
108	const BeamSegment = ({ i }: { i: number }) => (
109	  <span aria-hidden className="beam-seg" style={{ "--i": i } as CSSProperties}>
110	    <span className="beam-fill" />
111	    <span className="beam-head" />
112	  </span>
113	);
114	
115	/**
116	 * Check, Diagnose, Repair, Prove: each tab streams a real excerpt and shows real stat cards.
117	 * A single beam runs the connector between the four stages once, when the list first comes into
118	 * view, and the connector then holds its drawn state. Nothing else in the section moves while it
119	 * runs: the excerpt and the stat tickers wait for `onBeamDone`.
120	 */
121	export function SolutionTabs({ detail, onBeamDone }: { detail: RunDetail; onBeamDone?: () => void }) {
122	  const reduce = useReducedMotion();
123	  const [tab, setTab] = useState<TabKey>("check");
124	  const [manual, setManual] = useState(false);
125	  const [held, setHeld] = useState(false);
126	  const [inView, setInView] = useState(false);
127	  const box = useRef<HTMLDivElement>(null);
128	
129	  // The beam: --beam (0 to 1) is written on the connector's wrapper; every segment and node reads its part.
130	  const rail = useRef<HTMLDivElement>(null);
131	  const [beamDone, setBeamDone] = useState(false);
132	  const beamCb = useRef(onBeamDone);
133	  beamCb.current = onBeamDone;
134	  const [railSeen, setRailSeen] = useState(false);
135	  useEffect(() => {
136	    const el = rail.current;
137	    if (!el || typeof IntersectionObserver === "undefined") {
138	      setRailSeen(true);
139	      return;
140	    }
141	    // Also counts as seen when the list is already above the viewport (a jump or a restored scroll).
142	    const io = new IntersectionObserver(([e]) => {
143	      if (e.isIntersecting || e.boundingClientRect.top < 0) {
144	        setRailSeen(true);
145	        io.disconnect();
146	      }
147	    }, { rootMargin: "0px 0px -20% 0px" });
148	    io.observe(el);
149	    return () => io.disconnect();
150	  }, []);
151	  useEffect(() => {
152	    const el = rail.current;
153	    if (!railSeen || !el || beamDone) return;
154	    const finish = () => {
155	      setBeamDone(true);
156	      beamCb.current?.();
157	    };
158	    if (reduce) {
159	      el.style.setProperty("--beam", "1");
160	      finish();
161	      return;
162	    }
163	    let run: { stop: () => void } | undefined;
164	    const lead = window.setTimeout(() => {
165	      run = animate(0, 1, {
166	        duration: BEAM_MS / 1000,
167	        ease: EASE_ENTER,
168	        onUpdate: (v) => el.style.setProperty("--beam", String(v)),
169	        onComplete: finish,
170	      });
171	    }, BEAM_LEAD_MS);
172	    return () => {
173	      window.clearTimeout(lead);
174	      run?.stop();
175	    };
176	  }, [railSeen, reduce, beamDone]);
177	
178	  useEffect(() => {
179	    const el = box.current;
180	    if (!el || typeof IntersectionObserver === "undefined") return;
181	    const io = new IntersectionObserver(([e]) => setInView(e.isIntersecting), { threshold: 0.3 });
182	    io.observe(el);
183	    return () => io.disconnect();
184	  }, []);
185	
186	  // Anticipation: the tab indicator moves first; the content swaps ~160 ms later.
187	  const [shownTab, setShownTab] = useState<TabKey>(tab);
188	  useEffect(() => {
189	    if (reduce) {
190	      setShownTab(tab);
191	      return;
192	    }
193	    const id = window.setTimeout(() => setShownTab(tab), 160);
194	    return () => window.clearTimeout(id);
195	  }, [tab, reduce]);
196	
197	  const c = useMemo(() => contentFor(shownTab, detail), [shownTab, detail]);
198	  const joined = c.lines.map((l) => l.text).join("\n");
199	  const { shown, done } = useStream(joined, { restartKey: shownTab, enabled: (inView || manual) && beamDone });
200	
201	  // Stay long enough to read what streamed, plus the stat labels: 250 ms and 30 ms a word.
202	  const readMs = Math.max(1800, readingMs(`${joined} ${c.stats.map((s) => `${s.label} ${s.value}`).join(" ")}`));
203	  useEffect(() => {
204	    if (reduce || manual || held || !done || !inView || !beamDone || shownTab !== tab) return;
205	    const i = TABS.findIndex((t) => t.id === tab);
206	    const id = window.setTimeout(() => setTab(TABS[(i + 1) % TABS.length].id), readMs);
207	    return () => window.clearTimeout(id);
208	  }, [reduce, manual, held, done, inView, beamDone, tab, shownTab, readMs]);
209	
210	  const visible = shown.split("\n");
211	
212	  return (
213	    <div
214	      ref={box}
215	      className="mt-12 grid gap-8 lg:grid-cols-[18rem_minmax(0,1fr)]"
216	      onMouseEnter={() => setHeld(true)}
217	      onMouseLeave={() => setHeld(false)}
218	      onFocus={() => setHeld(true)}
219	      onBlur={() => setHeld(false)}
220	    >
221	      <div ref={rail} className="min-w-0">
222	      <TabList
223	        prefix="sol"
224	        label="Stages"
225	        orientation="vertical"
226	        tabs={TABS}
227	        value={tab}
228	        onChange={(id, byUser) => {
229	          if (byUser) setManual(true);
230	          setTab(id);
231	        }}
232	        className="flex gap-2 overflow-x-auto pt-5 lg:flex-col lg:overflow-visible lg:pl-5 lg:pt-0"
233	        tabClassName={(sel) =>
234	          cn(
235	            "chip-t relative flex min-w-40 items-start gap-3 rounded-lg border px-4 py-3 text-left",
236	            sel ? "border-accent-strong bg-panel" : "border-transparent text-muted-foreground hover:bg-panel",
237	          )
238	        }
239	        render={(t) => {
240	          const tt = TABS.find((x) => x.id === t.id)!;
241	          const n = TABS.indexOf(tt);
242	          return (
243	            <>
244	              <AnimIcon name={tt.icon} className="mt-0.5 size-5 shrink-0" />
245	              <span>
246	                <span className="block font-semibold text-foreground">{tt.label}</span>
247	                <span className="mt-0.5 hidden text-sm lg:block">{tt.blurb}</span>
248	              </span>
249	              {n < TABS.length - 1 && <BeamSegment i={n} />}
250	              <BeamNode i={n} />
251	            </>
252	          );
253	        }}
254	      />
255	      </div>
256	      <div role="tabpanel" id={panelId("sol", tab)} aria-labelledby={tabId("sol", tab)} className="min-w-0 rounded-xl border border-border bg-panel p-4 sm:p-6">
257	        <div className="overflow-hidden rounded-lg border border-border bg-terminal text-terminal-ink">
258	          <p className="border-b border-border bg-panel px-3 py-2 font-mono text-xs text-muted-foreground">{c.title}</p>
259	          <pre className="m-0 min-h-[10rem] overflow-x-auto whitespace-pre-wrap break-words p-3 font-mono text-[13px] leading-relaxed">
260	            {visible.map((t, i) => {
261	              const tone = c.lines[i]?.tone;
262	              return (
263	                <span
264	                  key={i}
265	                  className={cn(
266	                    "block",
267	                    tone === "bad" && "text-broken",
268	                    tone === "good" && "text-runs",
269	                    tone === "muted" && "text-muted-foreground",
270	                    tone === "added" && "bg-evidence text-on-evidence",
271	                  )}
272	                >
273	                  {t || " "}
274	                  {i === visible.length - 1 && !done && <span className="stream-cursor" />}
275	                </span>
276	              );
277	            })}
278	          </pre>
279	        </div>
280	        {c.stats.length > 0 && (
281	          <dl className="mt-4 grid gap-3 sm:grid-cols-2 xl:grid-cols-4">
282	            {c.stats.map((s, i) => (
283	              // Follow-through: the stat cards trail the excerpt, one after another.
284	              <div
285	                key={`${shownTab}-${s.label}`}
286	                style={{ "--i": i + 1 } as CSSProperties}
287	                className="settle rounded-lg border border-border bg-canvas p-4"
288	              >
289	                <dd className="font-mono text-2xl font-semibold tabular-nums">{s.value}</dd>
290	                <dt className="mt-1 text-sm text-muted-foreground">{s.label}</dt>
291	              </div>
292	            ))}
293	          </dl>
294	        )}
295	        <p className="mt-3 text-xs text-muted-foreground">
296	          {reduce ? "" : manual ? "" : "Advances on its own. Select a tab to hold it. "}
297	          Excerpts and numbers are read from the recorded run of {detail.result.repo}.
298	        </p>
299	      </div>
300	    </div>
301	  );
302	}
