// node probe.mjs <path> <width> [theme] [shotFile] [selector] [scrollIntoView selector]
import { spawn } from "node:child_process";
import { writeFileSync, mkdirSync } from "node:fs";
import { join, dirname } from "node:path";

const [path, width = "360", theme = "light", shot, sel, mobile] = process.argv.slice(2);
const base = process.env.BASE ?? "http://REDACTED:8787";
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const port = 9300 + Math.floor(Math.random() * 600);
const prof = join(dirname(new URL(import.meta.url).pathname), ".probe-profile-" + port);
const proc = spawn("chromium", ["--headless=new", "--disable-gpu", "--no-sandbox", `--remote-debugging-port=${port}`, `--user-data-dir=${prof}`, "about:blank"], { stdio: "ignore" });
let tab;
for (let i = 0; i < 50 && !tab; i++) {
  try { tab = (await (await fetch(`http://REDACTED:${port}/json`)).json()).find((t) => t.type === "page"); } catch {}
  if (!tab) await sleep(200);
}
const ws = new WebSocket(tab.webSocketDebuggerUrl);
await new Promise((r) => (ws.onopen = r));
let n = 0;
const waiting = new Map();
ws.onmessage = (m) => { const d = JSON.parse(m.data); waiting.get(d.id)?.(d); };
const send = (method, params = {}) => new Promise((res) => { waiting.set(++n, res); ws.send(JSON.stringify({ id: n, method, params })); });
const value = async (e) => (await send("Runtime.evaluate", { expression: e, returnByValue: true, awaitPromise: true })).result.result.value;

await send("Emulation.setDeviceMetricsOverride", { width: +width, height: 800, deviceScaleFactor: 1, mobile: false });
await send("Emulation.setEmulatedMedia", { features: [{ name: "prefers-color-scheme", value: theme }] });
await send("Page.navigate", { url: base + path });
await sleep(+(process.env.WAIT ?? 4500));
const probe = `(() => {
  const vw = document.documentElement.clientWidth;
  const name = (e) => e.tagName.toLowerCase() + '.' + String(e.getAttribute('class') || '').split(/\\s+/).slice(0, 4).join('.');
  const over = [...document.querySelectorAll('body *')].filter((e) => { const r = e.getBoundingClientRect(); return r.width && r.right > vw + 1; })
    .map((e) => name(e) + ' right=' + Math.round(e.getBoundingClientRect().right) + ' w=' + Math.round(e.getBoundingClientRect().width)).slice(0, 12);
  return JSON.stringify({ vw, sw: document.documentElement.scrollWidth, bodySw: document.body.scrollWidth, over });
})()`;
console.log(await value(probe));
if (process.env.EVAL) console.log(await value(process.env.EVAL));
if (shot) {
  mkdirSync(dirname(shot), { recursive: true });
  let params = { format: "png" };
  if (sel) {
    await value(`document.querySelector(${JSON.stringify(sel)})?.scrollIntoView({block:'center'})`);
    await sleep(1800);
    const box = JSON.parse(await value(`(() => { const e = document.querySelector(${JSON.stringify(sel)}); if (!e) return 'null'; const r = e.getBoundingClientRect(); return JSON.stringify({x: Math.max(0, r.left + scrollX), y: r.top + scrollY, width: r.width, height: r.height}); })()`));
    if (box) params.clip = { ...box, scale: 1 };
  } else {
    const h = await value("document.documentElement.scrollHeight");
    await send("Emulation.setDeviceMetricsOverride", { width: +width, height: Math.min(h, 6000), deviceScaleFactor: 1, mobile: false });
  }
  writeFileSync(shot, Buffer.from((await send("Page.captureScreenshot", params)).result.data, "base64"));
  console.log("shot", shot);
}
ws.close();
proc.kill();
process.exit(0);

